import fs from 'node:fs';
let raw = fs.readFileSync('/tmp/cap_out.txt', 'utf8').trim();
// eval output is a JSON-quoted string
let src = raw;
if (raw.startsWith('"')) {
  try { src = JSON.parse(raw); } catch { src = raw.replace(/^"|"$/g, ''); }
}
const b64 = src.replace(/^data:image\/\w+;base64,/, '');
fs.writeFileSync('/tmp/captcha7043.gif', Buffer.from(b64, 'base64'));
console.log('written', Buffer.from(b64, 'base64').length, 'bytes; prefix:', src.slice(0, 40));

